import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, color, mix, smoothstep, length, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, PointLight, DirectionalLight, Box3, Vector3 } = ctx.THREE;

  const root = new Group();
  root.name = 'orbit-product-hero';

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.55, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];

  // ---------------------------------------------------------------
  // BACKDROP — 7x6 engineered vertical gradient plane at z = -2.5
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const vY = uv().y;
  const c0 = color(stops[0].hex);
  const c1 = color(stops[1]?.hex ?? stops[0].hex);
  const c2 = color(stops[2]?.hex ?? stops[1]?.hex ?? stops[0].hex);
  const midAt = float(stops[1]?.at ?? 0.55);
  const grad = mix(
    mix(c0, c1, smoothstep(float(0.0), midAt, vY)),
    c2,
    smoothstep(midAt, float(1.0), vY)
  );
  backdropMat.colorNode = grad;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.25, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // SUBJECT GROUP (watch + plinth orbit together)
  // ---------------------------------------------------------------
  const subject = new Group();
  subject.name = 'subject';
  root.add(subject);

  // Plinth — low cylinder, radius 1.4, height 0.25, top face at y = -1.1
  const plinthGeo = new CylinderGeometry(1.4, 1.45, 0.25, 64);
  const plinthMat = new MeshStandardNodeMaterial({
    color: colors.surface ?? '#14141a',
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.y = -1.225; // top face at -1.1
  subject.add(plinth);
  disposables.push(plinthGeo, plinthMat);

  // Contact shadow — radial gradient plane, radius 1.6, opacity 0.55
  const shadowGeo = new PlaneGeometry(3.2, 3.2);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  const dist = length(uv().sub(0.5)).mul(2.0);
  shadowMat.opacityNode = smoothstep(float(1.0), float(0.15), dist).mul(0.55);
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -1.36;
  root.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // Watch mesh — loaded async, normalized to 2.2 units tall, base at plinth top
  const watchHolder = new Group();
  watchHolder.name = 'watch-holder';
  subject.add(watchHolder);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene;
      const box = new Box3().setFromObject(scene);
      const size = new Vector3();
      box.getSize(size);
      const scale = 2.2 / Math.max(size.y, 1e-6);
      scene.scale.setScalar(scale);

      // Recenter so the mesh spans y in [-1.1, 1.1], centered on x/z
      const box2 = new Box3().setFromObject(scene);
      const center = new Vector3();
      box2.getCenter(center);
      scene.position.x -= center.x;
      scene.position.z -= center.z;
      scene.position.y -= box2.min.y + 1.1; // bottom rests at y = -1.1

      // Brushed-metal PBR discipline (keep GLB textures, tune response)
      scene.traverse((child) => {
        if (child.isMesh && child.material) {
          const m = child.material;
          if ('roughness' in m) m.roughness = 0.52;
          if ('metalness' in m) m.metalness = 0.55;
          if ('clearcoat' in m) m.clearcoat = 0.2;
          if ('clearcoatRoughness' in m) m.clearcoatRoughness = 0.4;
          m.needsUpdate = true;
        }
      });

      watchHolder.add(scene);

      // Entrance: rise-in + weighted settle
      watchHolder.position.y = 0.4;
      watchHolder.scale.setScalar(0.96);
      const tlIn = gsap.timeline();
      tlIn.to(watchHolder.position, { y: 0, duration: 0.7, ease: 'power3.out' });
      tlIn.to(watchHolder.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power2.out' }, 0.2);
      tlIn.to(watchHolder.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, '>');
      timelines.push(tlIn);
    });
  }

  // ---------------------------------------------------------------
  // LIGHTING — accent rim grazing the left case flank + cool back rim
  // (scene supplies ambient 0.6 + key 1.2; these are node-local)
  // ---------------------------------------------------------------
  const accentRim = new PointLight(colors.accent ?? '#ff2a38', 1.4, 12, 2);
  accentRim.position.set(-3.2, 0.6, -1.0);
  root.add(accentRim);

  const backRim = new DirectionalLight(colors.paper ?? '#e8ecf2', 0.7);
  backRim.position.set(2.5, 2.0, -3.0);
  backRim.target = subject;
  root.add(backRim);

  // ---------------------------------------------------------------
  // TYPE — verbatim spec copy, bimodal scale
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.name = 'copy';
  textGroup.position.z = 1.0;
  root.add(textGroup);

  const yByRole = { headline: -1.5, body: -1.85, caption: -2.15 };
  let fallbackY = -1.5;
  for (const item of items) {
    const roleY = yByRole[item.role] ?? fallbackY;
    fallbackY -= 0.35;
    const fontSize = item.typography?.fontSize ?? (item.role === 'headline' ? 68 : item.role === 'body' ? 26 : 18);
    const isCaption = item.role === 'caption';
    const t = ctx.fontAtlas.createText(String(item.text), {
      fontSize,
      color: isCaption ? (colors.accent ?? '#ff2a38') : (colors.paper ?? '#e8ecf2'),
      align: 'center',
      letterSpacingPx: isCaption ? fontSize * 0.08 : 0,
    });
    t.position.set(0, roleY, 0);
    textGroup.add(t);
  }

  // Copy entrance: fade-up
  textGroup.position.y = -0.2;
  const tlText = gsap.timeline();
  tlText.to(textGroup.position, { y: 0, duration: 0.5, ease: 'power2.out', delay: 0.25 });
  timelines.push(tlText);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES — apply every one from config
  // ---------------------------------------------------------------
  for (const primitive of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[primitive.name];
    if (fn) {
      const handle = fn(subject, primitive.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // HANDLERS + CLEANUP
  // ---------------------------------------------------------------
  root.userData.handlers = {
    hover: () => {
      gsap.to(watchHolder.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 0.3, ease: 'power2.out' });
    },
    hoverEnd: () => {
      const tl = gsap.timeline();
      tl.to(watchHolder.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.2, ease: 'power2.out' });
      tl.to(watchHolder.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
      timelines.push(tl);
    },
  };

  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primitiveHandles) {
      if (h.timeline) h.timeline.kill && h.timeline.kill();
      if (h.cleanup) h.cleanup();
    }
    for (const d of disposables) d.dispose && d.dispose();
    watchHolder.traverse((child) => {
      if (child.isMesh) {
        child.geometry && child.geometry.dispose();
        if (child.material) {
          Array.isArray(child.material)
            ? child.material.forEach((m) => m.dispose())
            : child.material.dispose();
        }
      }
    });
  };

  return root;
}
